package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Inbox mascot: a dachshund leaning out from behind a blank card.
 *
 * The card is what an inbox holds and this one has nothing written on it, with
 * two pale dashes standing in for the lines that are not there yet. The dog is
 * looking at it rather than sleeping on it, because Inbox is the screen the
 * user is about to put something into.
 *
 * Exported from the board, node `883:6049`. [MascotImage] explains why the
 * paths are built in Kotlin, and which colour role each tone takes.
 */
@Composable
internal fun InboxMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::dogBehindACard
    )
}

private const val MascotWidth = 240f
private const val MascotHeight = 146.136f

/** Where the artwork sits inside the frame the board draws it in. */
private const val ArtworkOffsetX = 9.072f
private const val ArtworkOffsetY = 8.154f

private fun dogBehindACard(pale: Color, body: Color, detail: Color): ImageVector =
    ImageVector.Builder(
        name = "InboxDogBehindACard",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = MascotWidth,
        viewportHeight = MascotHeight
    )
        .addGroup(translationX = ArtworkOffsetX, translationY = ArtworkOffsetY)
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(Jaw),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(CardEdge),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(Ear),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Eye),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Card),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(DashUpper),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(DashLower),
            fill = SolidColor(body)
        )
        .clearGroup()
        .build()

